"use client";

import { useState, useEffect, useMemo } from "react";
import { useSearchParams, useRouter } from "next/navigation";
import { useTranslations } from "next-intl";
import { createClient } from "@/lib/supabase/client";
import { ListSkeleton } from "@/components/Skeletons";
import ErrorBoundary from "@/components/ErrorBoundary";
import PosterImage from "@/components/PosterImage";
import EmptyState from "@/components/EmptyState";
import { titleHref } from "@/lib/title-utils";

// ─── Types ───
interface LibraryItem {
  tmdbId: number; mediaType: string; status: string; rating: number | null;
  progress: number | null; updatedAt: string; title: string; poster: string | null;
  year: number | null; tmdbRating: number;
  seasonNumber: number; seasonName: string | null; seasonPoster: string | null;
}
interface Collection { id: string; name: string; isPublic: boolean; isPublished: boolean; itemCount: number; createdAt: string; }
interface CollectionItem { tmdbId: number; mediaType: string; seasonNumber: number; title: string; poster: string | null; year: number | null; rating: number; note: string | null; addedAt: string; }

function getTabs(t: any) { return [
  { key: "plan_to_watch", label: t("libraryPage.toWatch") },
  { key: "watching", label: t("libraryPage.watching") },
  { key: "completed", label: t("libraryPage.watched") },
]; }

function getSortOptions(t: any) { return [
  { key: "recent", label: t("libraryPage.recent") },
  { key: "rating", label: t("libraryPage.myRating") },
  { key: "popularity", label: t("libraryPage.popular") },
  { key: "year", label: t("libraryPage.year") },
] as const; }
type SortKey = "recent" | "rating" | "popularity" | "year";

// ─── Tracking grid ───
function TrackingGrid({ activeTab }: { activeTab: string }) {
  const t = useTranslations();
  const [items, setItems] = useState<LibraryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [sort, setSort] = useState<SortKey>("recent");
  const [localUser, setLocalUser] = useState<string | null>(null);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [total, setTotal] = useState(0);
  const LIMIT = 50;
  const supabase = createClient();

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setLocalUser(session?.user?.user_metadata?.username || null);
    }).catch(() => {});
  }, []);

  function fetchPage(p: number) {
    if (!localUser) { setLoading(false); return; }
    const username = localUser;
    const url = activeTab
      ? `/api/library?username=${encodeURIComponent(username)}&status=${activeTab}&page=${p}&limit=${LIMIT}`
      : `/api/library?username=${encodeURIComponent(username)}&page=${p}&limit=${LIMIT}`;
    setLoading(true);
    setPage(p);
    fetch(`${url}&_t=${Date.now()}`, { cache: "no-cache" })
      .then(r => r.json())
      .then(data => {
        setItems(data.items || []);
        setTotal(data.total || 0);
        setTotalPages(data.totalPages || 0);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }

  useEffect(() => { fetchPage(1); }, [activeTab, localUser]);

  const sortedItems = useMemo(() => {
    const filtered = items.filter(item => {
      if (item.mediaType === "movie") return true;
      if (item.mediaType === "anime") return true;
      return item.seasonNumber > 0;
    });
    const sorted = [...filtered];
    switch (sort) {
      case "rating": sorted.sort((a, b) => (b.rating ?? 0) - (a.rating ?? 0)); break;
      case "popularity": sorted.sort((a, b) => (b.tmdbRating ?? 0) - (a.tmdbRating ?? 0)); break;
      case "year": sorted.sort((a, b) => (b.year ?? 0) - (a.year ?? 0)); break;
      default: break;
    }
    return sorted;
  }, [items, sort]);

  if (!localUser) return <EmptyState icon="signin" title={t("library.signInTitle")} description={t("library.signInDesc")} action={{ label: t("library.signInAction"), href: "/signup" }} />;
  if (loading) return <ListSkeleton rows={6} />;
  if (total === 0) return <EmptyState icon="empty" title={activeTab ? `No ${getTabs(t).find(tab=>tab.key===activeTab)?.label || "items"} yet` : "Your library is empty"} description="Start tracking movies and shows to build your collection." action={{ label: "Discover titles", href: "/" }} />;

  return (
    <div className="max-w-4xl mx-auto px-4 mt-4">
      {/* Sort bar */}
      <div className="flex gap-1.5 mb-3">
        {getSortOptions(t).map(opt => (
          <button
            key={opt.key}
            onClick={() => setSort(opt.key)}
            className={`px-3 py-1 rounded-full text-[11px] font-medium transition-colors ${
              sort === opt.key
                ? "bg-accent text-white"
                : "bg-bg-card text-text-secondary hover:text-text-primary"
            }`}
          >
            {opt.label}
          </button>
        ))}
      </div>

      <div className="grid grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-3">
        {sortedItems.map(item => {
        // 시즌 표기는 TV에만 붙인다. 애니는 시즌이 항목 자체로 나뉘어 있고(AniList),
        // 작품 행의 시즌 라벨은 1로 통일되어 있어 그대로 두면 카드에 'S1'이 표시된다.
        const isSeason = item.mediaType === "tv" && item.seasonNumber > 0;
        const displayPoster = isSeason && item.seasonPoster ? item.seasonPoster : item.poster;
        const displayTitle = isSeason && item.seasonName
          ? `${item.title} — ${item.seasonName}`
          : item.title;
        const itemKey = `${item.mediaType}-${item.tmdbId}-${item.seasonNumber}`;
        const itemHref = isSeason && item.mediaType === "tv"
          ? `/tv/${item.tmdbId}/season/${item.seasonNumber}`
          : titleHref(item.tmdbId, item.mediaType);
        return (
        <a key={itemKey} href={itemHref} className="block group">
          <div className="relative aspect-[2/3] rounded-xl overflow-hidden bg-bg-card">
            {displayPoster ? <PosterImage src={displayPoster} alt={displayTitle} fill className="rounded-xl group-hover:scale-105 transition-transform duration-300" sizes="(max-width: 768px) 33vw, 200px" /> : <div className="w-full h-full flex items-center justify-center text-text-primary/20 text-2xl font-bold">{displayTitle.slice(0,2)}</div>}
            <div className="absolute top-2 left-2"><span className={`px-1.5 py-0.5 rounded text-[10px] font-semibold ${item.status==="completed"?"bg-green-500/20 text-green-400":item.status==="watching"?"bg-blue-500/20 text-blue-400":"bg-amber-500/20 text-amber-400"}`}>{item.status==="completed"?t("libraryPage.watched"):item.status==="watching"?t("libraryPage.watching"):t("libraryPage.toWatch")}</span></div>
            {item.tmdbRating > 0 && <div className="absolute top-2 right-2 bg-black/60 backdrop-blur-sm rounded-full px-1.5 py-0.5 text-[10px] font-semibold text-gold">★ {item.tmdbRating}</div>}
            {item.rating && <div className="absolute bottom-2 left-2 bg-black/60 backdrop-blur-sm rounded-full px-1.5 py-0.5 text-[10px] font-semibold text-pink-400">★ {item.rating}</div>}
          </div>
          <p className="mt-1.5 text-xs font-medium text-text-primary leading-tight line-clamp-2 group-hover:text-accent transition-colors">{displayTitle}</p>
          <p className="text-[10px] text-text-secondary">{item.year || "—"} · {item.mediaType==="movie"?"Movie":item.mediaType==="anime"?"Anime":"TV"}{isSeason ? ` · S${item.seasonNumber}` : ""}</p>
        </a>
        )})}
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-center gap-3 mt-6 pb-4">
          <button
            onClick={() => fetchPage(page - 1)}
            disabled={page <= 1}
            className="px-3 py-1.5 rounded-lg bg-bg-card text-text-primary text-xs font-medium disabled:opacity-30 hover:bg-bg-surface transition-colors"
          >
            ← Prev
          </button>
          <span className="text-xs text-text-secondary">
            {page} / {totalPages}
          </span>
          <button
            onClick={() => fetchPage(page + 1)}
            disabled={page >= totalPages}
            className="px-3 py-1.5 rounded-lg bg-bg-card text-text-primary text-xs font-medium disabled:opacity-30 hover:bg-bg-surface transition-colors"
          >
            Next →
          </button>
        </div>
      )}
    </div>
  );
}

// ─── Collections view ───
function CollectionsView() {
  const t = useTranslations();
  const [collections, setCollections] = useState<Collection[]>([]);
  const [loading, setLoading] = useState(true);
  const [newName, setNewName] = useState("");
  const [creating, setCreating] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [items, setItems] = useState<CollectionItem[]>([]);
  const [itemsLoading, setItemsLoading] = useState(false);
  const [authUser, setAuthUser] = useState<{ email?: string; user_metadata?: { username?: string } } | null>(null);
  const [publishFeedback, setPublishFeedback] = useState<string | null>(null);
  const [publishingId, setPublishingId] = useState<string | null>(null);
  const [isPremium, setIsPremium] = useState(false);
  const supabase = createClient();
  const authUsername = authUser?.user_metadata?.username;
  const username = typeof window !== "undefined" && authUsername ? authUsername : "";

  const fetchCollections = () => {
    setLoading(true);
    Promise.all([
      fetch(`/api/collections?username=${encodeURIComponent(username)}`).then(r => r.json()),
      fetch(`/api/premium?username=${encodeURIComponent(username)}`).then(r => r.json()),
    ])
      .then(([collData, premiumData]) => {
        setCollections(collData.collections || []);
        setIsPremium(premiumData.is_premium || false);
        setLoading(false);
      }).catch(() => setLoading(false));
  };

  useEffect(() => { fetchCollections(); supabase.auth.getSession().then(({ data: { session } }) => setAuthUser(session?.user ?? null)).catch(() => {}); }, []);

  const fetchItems = (listId: string) => {
    setItemsLoading(true);
    fetch(`/api/collections/${listId}/items?username=${encodeURIComponent(username)}`)
      .then(r => r.json()).then(d => { setItems(d.items || []); setItemsLoading(false); }).catch(() => setItemsLoading(false));
  };

  const createCollection = async () => {
    if (!newName.trim() || creating || !authUser) return;
    setCreating(true);
    setErrorMsg(null);
    try {
      const res = await fetch("/api/collections", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ username, name: newName.trim() }) });
      if (res.ok) { setNewName(""); fetchCollections(); }
      else { const data = await res.json().catch(() => ({})); setErrorMsg(data.error || "Failed to create collection"); }
    } catch {
      setErrorMsg("Network error — please try again");
    }
    setCreating(false);
  };

  const deleteCollection = async (id: string) => {
    await fetch("/api/collections", { method: "DELETE", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ username, listId: id }) });
    if (selectedId === id) setSelectedId(null);
    fetchCollections();
  };

  const removeItem = async (listId: string, tmdbId: number, mediaType: string, seasonNumber: number = 0) => {
    await fetch(`/api/collections/${listId}/items`, { method: "DELETE", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ username, tmdbId, mediaType, seasonNumber }) });
    fetchItems(listId); fetchCollections();
  };

  const togglePublish = async (listId: string) => {
    setPublishingId(listId);
    setPublishFeedback(null);
    try {
      const res = await fetch(`/api/collections/${listId}/publish`, { method: "POST" });
      const json = await res.json();
      if (res.ok) {
        setPublishFeedback(json.message || (json.isPublished ? "Published ✓" : "Now private ✓"));
        fetchCollections();
      } else {
        setPublishFeedback(json.error || "Failed to publish");
      }
    } catch {
      setPublishFeedback("Network error — try again");
    }
    setPublishingId(null);
    setTimeout(() => setPublishFeedback(null), 3500);
  };

  if (selectedId) {
    const collection = collections.find(c => c.id === selectedId);
    return (
      <div className="max-w-4xl mx-auto px-4 mt-4">
        <div className="flex items-center gap-3 mb-4">
          <button onClick={() => setSelectedId(null)} className="text-text-secondary hover:text-text-primary text-sm">← Back</button>
          <h2 className="text-lg font-semibold text-text-primary">{collection?.name}</h2>
          <span className="text-xs text-text-secondary">{items.length} items</span>
        </div>
        {itemsLoading ? <div className="flex justify-center py-10"><div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" /></div>
        : items.length === 0 ? <EmptyState icon="noitems" title="No items yet" description="Add movies and shows to this collection." action={{ label: "Browse titles", href: "/" }} />
        : <div className="grid grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3">
          {items.map(item => {
          const isItemSeason = item.mediaType === "tv" && item.seasonNumber > 0;
          const itemKey = `${item.mediaType}-${item.tmdbId}-${item.seasonNumber}`;
          const itemHref = isItemSeason && item.mediaType === "tv"
            ? `/tv/${item.tmdbId}/season/${item.seasonNumber}`
            : titleHref(item.tmdbId, item.mediaType);
          return (
            <div key={itemKey} className="relative group">
              <a href={itemHref} className="block">
                <div className="relative aspect-[2/3] rounded-xl overflow-hidden bg-bg-card">
                  {item.poster ? <PosterImage src={item.poster} alt={item.title} fill className="rounded-xl group-hover:scale-105 transition-transform duration-300" sizes="(max-width: 768px) 33vw, 200px" /> : <div className="w-full h-full flex items-center justify-center text-text-primary/20 text-2xl font-bold">{item.title.slice(0,2)}</div>}
                  {item.rating > 0 && <div className="absolute top-2 right-2 bg-black/60 backdrop-blur-sm rounded-full px-1.5 py-0.5 text-[10px] font-semibold text-gold">★ {item.rating}</div>}
                  <button onClick={(e) => { e.preventDefault(); e.stopPropagation(); removeItem(selectedId, item.tmdbId, item.mediaType, item.seasonNumber); }} className="absolute top-2 left-2 w-6 h-6 rounded-full bg-red-600/80 hover:bg-red-600 text-white text-xs flex items-center justify-center z-10">✕</button>
                </div>
                <p className="mt-1.5 text-xs font-medium text-text-primary leading-tight line-clamp-2">{item.title}{isItemSeason ? ` · S${item.seasonNumber}` : ""}</p>
                <p className="text-[10px] text-text-secondary">{item.year||"—"} · {item.mediaType==="movie"?"Movie":"TV"}</p>
                {item.note && <p className="text-[10px] text-accent mt-0.5 line-clamp-2">"{item.note}"</p>}
              </a>
            </div>
          )})}
        </div>}
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto px-4 mt-4">
      {!authUser ? (
        <EmptyState icon="signin" title={t("library.collectionsSignInTitle")} description={t("library.collectionsSignInDesc")} action={{ label: t("library.collectionsSignInAction"), href: "/signup" }} />
      ) : (
      <>
      {(() => {
        return (
          <div className="mb-4">
            <div className="flex gap-2">
              <input value={newName} onChange={e => setNewName(e.target.value)} onKeyDown={e => e.key==="Enter" && createCollection()}
                placeholder={"New collection name..."}
                className="flex-1 bg-bg-card text-text-primary text-sm rounded-xl px-3 py-2 outline-none border border-border focus:border-accent placeholder:text-text-secondary" maxLength={50} />
              <button onClick={createCollection} disabled={creating || !newName.trim()}
                className="px-4 py-2 rounded-xl bg-accent text-white text-sm font-medium disabled:opacity-40 hover:bg-[#5558e7] transition-colors">Create</button>
            </div>
            {errorMsg && (
              <p className="mt-2 text-xs text-red-400">{errorMsg}</p>
            )}
          </div>
        );
      })()}
      {loading ? <div className="flex justify-center py-10"><div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" /></div>
      : collections.length === 0 ? <EmptyState icon="collections" title="No collections yet" description="Create your first collection to organize your favorite titles." />
      : <div className="space-y-2">
        {collections.map(c => (
          <div key={c.id} className="flex items-center gap-3 bg-bg-card rounded-xl p-3 hover:bg-bg-surface transition-colors cursor-pointer group" onClick={() => { setSelectedId(c.id); fetchItems(c.id); }}>
            <div className="flex-1 min-w-0"><p className="text-sm font-medium text-text-primary truncate">{c.name}</p><p className="text-xs text-text-secondary">{c.itemCount} item{c.itemCount !== 1 ? "s" : ""}</p></div>
            <button onClick={e => { e.stopPropagation(); togglePublish(c.id); }} disabled={publishingId === c.id} className={`text-[10px] font-medium px-2 py-1 rounded-lg transition-colors ${publishingId === c.id ? "opacity-50 cursor-wait" : ""} ${c.isPublished ? "bg-[#374151]/50 text-text-secondary hover:bg-[#374151]" : "bg-accent/10 text-[#818cf8] hover:bg-accent/20"}`}>{publishingId === c.id ? "..." : c.isPublished ? "Unpublish" : "Publish"}</button>
            <button onClick={e => { e.stopPropagation(); deleteCollection(c.id); }} className="text-text-secondary hover:text-red-400 text-lg opacity-0 group-hover:opacity-100 transition-opacity">🗑</button>
          </div>
        ))}
      </div>}
      {publishFeedback && (
        <div className={`mt-3 text-xs font-medium px-3 py-2 rounded-lg text-center ${
          publishFeedback.includes("✓") ? "bg-green-500/15 text-green-400" : "bg-red-500/15 text-red-400"
        }`}>{publishFeedback}</div>
      )}
      </>
      )}
    </div>
  );
}

// ─── Main Library ───
export default function LibraryClient() {
  const searchParams = useSearchParams();
  const router = useRouter();
  const tabFromUrl = searchParams.get("tab") as "completed" | "watching" | "plan_to_watch" | "collections" | null;
  const [activeFilter, setActiveFilter] = useState<"completed" | "watching" | "plan_to_watch" | "collections" | null>(
    tabFromUrl && ["completed", "watching", "plan_to_watch", "collections"].includes(tabFromUrl) ? tabFromUrl : "completed"
  );
  const [stats, setStats] = useState({ plan_to_watch: 0, watching: 0, completed: 0, collections: 0 });
  const [statsLoaded, setStatsLoaded] = useState(false);
  const [authUsername, setAuthUsername] = useState<string | null>(null);
  const supabase = createClient();

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setAuthUsername(session?.user?.user_metadata?.username || null);
    }).catch(() => {});
  }, []);

  // Sync activeFilter to URL
  function updateFilter(filter: "completed" | "watching" | "plan_to_watch" | "collections" | null) {
    setActiveFilter(filter);
    const params = new URLSearchParams(searchParams.toString());
    if (filter && filter !== "completed") {
      params.set("tab", filter);
    } else {
      params.delete("tab");
    }
    const qs = params.toString();
    router.replace(`/library${qs ? `?${qs}` : ""}`, { scroll: false });
  }

  useEffect(() => {
    if (!authUsername) { setStatsLoaded(true); return; }
    const username = authUsername;
    Promise.all([
      fetch(`/api/library/stats?username=${encodeURIComponent(username)}&_t=${Date.now()}`, { cache: "no-cache" }).then(r => r.json()),
      fetch(`/api/collections?username=${encodeURIComponent(username)}&_t=${Date.now()}`, { cache: "no-cache" }).then(r => r.json()),
    ])
      .then(([counts, collData]) => {
        setStats({
          completed: counts.completed || 0,
          watching: counts.watching || 0,
          plan_to_watch: counts.plan_to_watch || 0,
          collections: (collData.collections || []).length,
        });
        setStatsLoaded(true);
      })
      .catch(() => setStatsLoaded(true));
  }, [authUsername]);

  return (
    <div className="w-[896px] max-w-full mx-auto min-h-screen pb-24">
      <header className="sticky top-0 z-40 bg-bg-primary/95 backdrop-blur-md px-4 py-3 border-b border-border">
        <h1 className="text-xl font-bold bg-gradient-to-r from-[#6366f1] to-[#a855f7] bg-clip-text text-transparent">My List</h1>
      </header>

      {/* Stats bar */}
      {statsLoaded && (
        <div className="flex gap-3 px-4 py-3 border-b border-border">
          <button onClick={() => updateFilter(activeFilter === "completed" ? null : "completed")}
            className={`flex-1 text-center py-2 rounded-xl text-xs font-medium transition-all ${
              activeFilter === "completed"
                ? "bg-[#10b981]/10 text-[#10b981] border border-[#10b981]/30"
                : "bg-bg-card text-text-secondary hover:text-[#10b981]"
            }`}>
            <span className="block text-lg font-bold">{stats.completed}</span>WATCHED
          </button>
          <button onClick={() => updateFilter(activeFilter === "watching" ? null : "watching")}
            className={`flex-1 text-center py-2 rounded-xl text-xs font-medium transition-all ${
              activeFilter === "watching"
                ? "bg-[#3b82f6]/10 text-[#3b82f6] border border-[#3b82f6]/30"
                : "bg-bg-card text-text-secondary hover:text-[#3b82f6]"
            }`}>
            <span className="block text-lg font-bold">{stats.watching}</span>WATCHING
          </button>
          <button onClick={() => updateFilter(activeFilter === "plan_to_watch" ? null : "plan_to_watch")}
            className={`flex-1 text-center py-2 rounded-xl text-xs font-medium transition-all ${
              activeFilter === "plan_to_watch"
                ? "bg-gold/10 text-gold border border-gold/30"
                : "bg-bg-card text-text-secondary hover:text-gold"
            }`}>
            <span className="block text-lg font-bold">{stats.plan_to_watch}</span>TO WATCH
          </button>
          <button onClick={() => updateFilter(activeFilter === "collections" ? null : "collections")}
            className={`flex-1 text-center py-2 rounded-xl text-xs font-medium transition-all ${
              activeFilter === "collections"
                ? "bg-accent-light/10 text-accent-light border border-[#a855f7]/30"
                : "bg-bg-card text-text-secondary hover:text-accent-light"
            }`}>
            <span className="block text-lg font-bold">{stats.collections}</span>COLLECTIONS
          </button>
        </div>
      )}

      {/* Content */}
      {!activeFilter ? (
        <div className="max-w-4xl mx-auto px-4 mt-4">
          <EmptyState icon="empty" title="Your list is empty" description="Start tracking movies and shows to build your collection." action={{ label: "Discover titles", href: "/" }} />
        </div>
      ) : activeFilter === "collections" ? (
        <CollectionsView />
      ) : (
        <TrackingGrid activeTab={activeFilter} />
      )}
    </div>
  );
}
